INSERT INTO feature VALUES('references-fidelity','workflow','A refreshed citation site held to its record',NULL,'implemented','ordinary',NULL,'A key line states what its site takes from the work, `newest`, `dependency` naming its section with `§`, `anchor` or `exemplar`, beside `lineage` and `background`. A site the citation refresh records in the references ledger''s `fidelity` table names the refactor for a historical verdict, the works traced from a sole cited work, and the anchor or its absence for a narrower newest work; `check:references` refuses such a site citing the replaced work, `lineage`, `background` or a bare locator, and a row whose site is gone.',NULL,'.config/references/fidelity.json .config/references/cases.json',NULL,NULL);
